// Command documents generated by UI tools (explorer actions now, the query bar later).
// They are written into a .mongo editor as pretty JSON, so users can read, edit and save them.

export type CollectionAction = "browse" | "sample" | "count" | "schema" | "indexes";

export const COLLECTION_ACTIONS: ReadonlyArray<{ id: CollectionAction; label: string; title: string }> = [
  { id: "browse", label: "Browse", title: "First 50 documents" },
  { id: "sample", label: "Sample", title: "20 random documents" },
  { id: "count", label: "Count", title: "Exact document count" },
  { id: "schema", label: "Schema", title: "Fields, how often they occur and their types (from a 1,000 document sample)" },
  { id: "indexes", label: "Indexes", title: "Index definitions" }
];

export const BROWSE_LIMIT = 50;
export const SAMPLE_SIZE = 20;
export const SCHEMA_SAMPLE_SIZE = 1000;

/** The command document for an explorer action on a collection. */
export function collectionCommand(action: CollectionAction, collection: string): Record<string, unknown> {
  switch (action) {
    case "browse":
      return { find: collection, filter: {}, limit: BROWSE_LIMIT };
    case "sample":
      return { aggregate: collection, pipeline: [{ $sample: { size: SAMPLE_SIZE } }], cursor: {} };
    case "count":
      return { count: collection };
    case "schema":
      return {
        aggregate: collection,
        pipeline: [
          { $sample: { size: SCHEMA_SAMPLE_SIZE } },
          { $project: { kv: { $objectToArray: "$$ROOT" } } },
          { $unwind: "$kv" },
          { $group: { _id: "$kv.k", count: { $sum: 1 }, types: { $addToSet: { $type: "$kv.v" } } } },
          { $sort: { count: -1, _id: 1 } }
        ],
        cursor: {}
      };
    case "indexes":
      return { listIndexes: collection };
  }
}

/** Distinct values of one field (from the explorer's Fields folder). */
export function distinctCommand(collection: string, field: string): Record<string, unknown> {
  return { distinct: collection, key: field, query: {} };
}

export function distinctTitle(collection: string, field: string): string {
  return tabTitle(`${collection}.${field}`, "Distinct");
}

/** Database statistics: data, storage and index sizes in bytes, object and collection counts. */
export function databaseStatsCommand(): Record<string, unknown> {
  return { dbStats: 1, scale: 1 };
}

export const SLOW_QUERY_LIMIT = 50;

/**
 * The slowest operations recorded by the database profiler. system.profile is a capped collection,
 * so it only holds recent operations, and it exists only once profiling has been turned on.
 */
export function slowQueriesCommand(): Record<string, unknown> {
  return {
    find: "system.profile",
    filter: {},
    sort: { millis: -1 },
    limit: SLOW_QUERY_LIMIT,
    projection: { _id: 0, ts: 1, op: 1, ns: 1, millis: 1, planSummary: 1, keysExamined: 1, docsExamined: 1, nreturned: 1, command: 1 }
  };
}

/** A collection's definition; its validator, validation level and action are under "options". */
export function validatorCommand(collection: string): Record<string, unknown> {
  return { listCollections: 1, filter: { name: collection } };
}

/** Tab title such as "orders (Browse)"; characters that are invalid in file names are replaced. */
export function tabTitle(subject: string, label: string): string {
  return `${subject} (${label})`.replace(/[<>:"/\\|?*]/g, "_").slice(0, 100);
}

/** Query text for an editor: the command as indented JSON with a trailing newline. */
export function commandText(command: Record<string, unknown>): string {
  return `${JSON.stringify(command, null, 2)}\n`;
}

export type TemplateKind = "find" | "aggregate" | "count" | "distinct";

/** Starting points for hand-written commands, with every common option present so it only needs editing, not looking up. */
export const TEMPLATES: ReadonlyArray<{ id: TemplateKind; label: string; title: string }> = [
  { id: "find", label: "find", title: "Filter, projection, sort, skip and limit" },
  { id: "aggregate", label: "aggregate", title: "A pipeline: $match, $group, $sort, $limit" },
  { id: "count", label: "count", title: "Count the documents matching a query" },
  { id: "distinct", label: "distinct", title: "The distinct values of a field" }
];

/** A template command on `collection` ("collection" when none is known yet). */
export function templateCommand(kind: TemplateKind, collection: string): Record<string, unknown> {
  const name = collection || "collection";
  switch (kind) {
    case "find":
      return { find: name, filter: {}, projection: {}, sort: { _id: 1 }, skip: 0, limit: BROWSE_LIMIT };
    case "aggregate":
      return {
        aggregate: name,
        pipeline: [
          { $match: {} },
          { $group: { _id: "$field", count: { $sum: 1 } } },
          { $sort: { count: -1 } },
          { $limit: BROWSE_LIMIT }
        ],
        cursor: {}
      };
    case "count":
      return { count: name, query: {} };
    case "distinct":
      return { distinct: name, key: "field", query: {} };
  }
}

/** Tab title for a collection action, e.g. "orders (Browse)". */
export function queryTitle(collection: string, action: CollectionAction): string {
  return tabTitle(collection, COLLECTION_ACTIONS.find((a) => a.id === action)?.label ?? action);
}
